from pathlib import Path
import gzip,json
import numpy as np,pandas as pd
from scipy.optimize import nnls,lsq_linear
R=Path(__file__).resolve().parent;V=R;S=Path('/workspace/scratch/TCGA_LIHC_candidate30_survival')
protocol={'reference_training':'GSE151530 only; locked_reference_manifest.json was saved before TCGA matching','expression':'Previous GSE62944 TCGA24 raw counts, all23368gene sum denominator, linear CP10k; same371primary01patients, outcome-blind sample selection','solver':'Primary NNLS with preserved training rowRMS scale and all supported components jointly fitted; normalize coefficients by sum. Fixed nonnegative ridge alpha=.01 sensitivity, no outcome selection','gene_matching':'Exact frozen training symbols measured inbulk; missing genes omitted from reference andbulk, never expression-zero imputed. No TCGA expression/survival used for discovery or gene ranking','output':'Relative target/totalmacrophage coefficients and target proportion within modeled macrophage coefficients. None calibrated tissue cell percentages. Median group is descriptive only; no new survival tests requested or performed in this turn','authorization':'User explicitly directs GSE151530-only candidate reference to TCGA; diagnostics do not veto exploratory application, limitations stay visible'}
(R/'TCGA_application_protocol.json').write_text(json.dumps(protocol,indent=2))
ref=pd.read_csv(V/'GSE151530_ONLY_EXPLORATORY_REFERENCE_CP10k.tsv',sep='\t',index_col=0);sc=pd.read_csv(V/'reference_row_scales.csv').set_index('gene');assert ref.index.equals(sc.index);ref.to_csv(R/'source_exploratory_reference.tsv',sep='\t');sc.to_csv(R/'source_reference_row_scales.csv');selection=pd.read_csv(S/'RNA_aliquot_selection.csv');keep=selection[selection.selected].copy().sort_values('patient');assert len(keep)==371 and keep.patient.is_unique;sample=keep['sample'].tolist();featuregenes=set(ref.index);raw={};lib=np.zeros(len(sample));rows=0
with gzip.open(S/'TCGA24_tumor_featurecounts.txt.gz','rt') as f:
 header=f.readline().rstrip('\r\n').split('\t')[1:];ix=pd.Index(header).get_indexer(sample);assert (ix>=0).all()
 for line in f:
  gene,sep,v=line.rstrip('\r\n').partition('\t');assert sep;counts=np.fromstring(v,sep='\t');assert len(counts)==len(header);vv=counts[ix];assert np.isfinite(vv).all() and (vv>=0).all();lib+=vv;rows+=1
  if gene in featuregenes:
   assert gene not in raw;raw[gene]=vv.copy()
  if rows%5000==0:print('Parsed',rows,'genes',flush=True)
assert np.allclose(lib,keep.assigned_gene_counts.to_numpy(),rtol=0,atol=1e-6);shared=ref.index[ref.index.isin(raw)];missing=ref.index[~ref.index.isin(raw)];assert 'PGAM5' in shared and len(shared)>=50
pd.DataFrame({'gene':ref.index,'bulk_available':ref.index.isin(raw),'used_for_fitting':ref.index.isin(raw)}).to_csv(R/'reference_bulk_gene_coverage.csv',index=False);pd.DataFrame({'gene':missing}).to_csv(R/'missing_reference_genes.csv',index=False);counts=pd.DataFrame({g:raw[g] for g in shared},index=keep.patient.to_numpy());counts.index.name='patient';y=counts.div(lib,axis=0)*1e4;counts.to_csv(R/'selected_patient_reference_gene_counts.csv.gz');y.to_csv(R/'selected_patient_reference_gene_CP10k.csv.gz');actualref=ref.loc[shared];scale=sc.loc[shared,'row_scale'].to_numpy();A=actualref.to_numpy()/scale[:,None];actualref.to_csv(R/'USED_EXPLORATORY_REFERENCE_CP10k.tsv',sep='\t');pd.DataFrame({'gene':shared,'row_scale':scale}).to_csv(R/'used_reference_row_scales.csv',index=False);coef=[];ridgecoef=[];diag=[];checks=[];target=ref.columns.get_loc('TAM_PGAM5_detected');mac=[ref.columns.get_loc(g) for g in ['TAM_PGAM5_detected','TAM_PGAM5_undetected','Cycling_TAM_PGAM5_undetected']]
for j,(pat,row) in enumerate(y.iterrows()):
 b=row.to_numpy()/scale;beta,res=nnls(A,b,maxiter=5000);w=beta/max(beta.sum(),1e-12);assert beta.sum()>0 and np.isfinite(w).all();coef.append(w);rb,_=nnls(np.vstack([A,np.sqrt(.01)*np.eye(A.shape[1])]),np.r_[b,np.zeros(A.shape[1])],maxiter=5000);rw=rb/max(rb.sum(),1e-12);ridgecoef.append(rw);diag.append({'patient':pat,'coefficient_sum_before_normalizing':float(beta.sum()),'weighted_residual':float(res),'weighted_relative_residual':float(res/max(np.linalg.norm(b),1e-12)),'target_coefficient_before_normalizing':float(beta[target]),'measured_reference_genes':len(shared)})
 if j%20==0:
  alt=lsq_linear(A,b,bounds=(0,np.inf),method='bvls',tol=1e-10,max_iter=1000);assert alt.success;aw=alt.x/max(alt.x.sum(),1e-12);err=float(abs(aw-w).max());assert err<1e-5;checks.append({'patient':pat,'max_normalized_coefficient_error':err,'NNLS_target':float(w[target]),'independent_solver_target':float(aw[target])})
weights=pd.DataFrame(coef,index=y.index,columns=ref.columns);weights.to_csv(R/'all_reference_component_estimates.csv');pd.DataFrame(ridgecoef,index=y.index,columns=ref.columns).to_csv(R/'ridge_sensitivity_component_estimates.csv');pd.DataFrame(diag).to_csv(R/'sample_fit_diagnostics.csv',index=False);pd.DataFrame(checks).to_csv(R/'independent_bounded_solver_checks.csv',index=False);values=weights.iloc[:,target];cut=float(values.median());bulk=pd.DataFrame({'patient':y.index,'RNA_sample':sample,'exploratory_target_fraction':values.to_numpy(),'exploratory_total_macrophage_fraction':weights.iloc[:,mac].sum(axis=1).to_numpy(),'PGAM5_log2_CPM_plus1':np.log2(y.PGAM5.to_numpy()*100+1),'assigned_gene_counts':lib,'group':np.where(values.to_numpy()>cut,'High','Low')});bulk['exploratory_target_within_macrophage_fraction']=bulk.exploratory_target_fraction/bulk.exploratory_total_macrophage_fraction.replace(0,np.nan);bulk.to_csv(R/'TCGA_LIHC_PGAM5_macrophage_estimates.csv',index=False)
assert np.allclose(weights.sum(axis=1),1);bulk['exploratory_target_percent']=bulk.exploratory_target_fraction*100;bulk.to_csv(R/'TCGA_LIHC_PGAM5_macrophage_estimates.csv',index=False)
summary={'unique_primary_patients':len(bulk),'whole_gene_rows':rows,'reference_genes_original':len(ref),'reference_genes_used':len(shared),'reference_genes_missing':len(missing),'measured_feature_coverage':len(shared)/len(ref),'reference_components':len(ref.columns),'score_median':cut,'cutpoint_percent':cut*100,'high_patients':int(bulk.group.eq('High').sum()),'low_patients':int(bulk.group.eq('Low').sum()),'exact_zero_target_estimates':int(values.eq(0).sum()),'median_tied_patients':int(values.eq(cut).sum()),'min_target_fraction':float(values.min()),'max_target_fraction':float(values.max()),'independent_solver_cases':len(checks),'TCGA_application_authorized_despite_failed_reference_validation':True,'interpretation':'Exploratory relative mixture coefficients, not calibrated cell infiltration abundance'};(R/'preparation_summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2),flush=True)
